"""Original oncologic emergencies: neutropenic infection."""
from qbank_authoring import question,ref
rows=[]
FN=ref('IDSA fever and neutropenia in cancer guideline','https://www.idsociety.org/practice-guideline/neutropenic-patients-with-cancer/')
NS=ref('NICE neutropenic sepsis guideline','https://www.nice.org.uk/guidance/cg151/chapter/recommendations')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A patient 9 days after chemotherapy has temperature 38.6°C, ANC 0.2 × 10^9/L and hypotension. What is the immediate principle?', 'Treat as a medical emergency with prompt IV antipseudomonal antibiotics and sepsis resuscitation',[
 ('Wait for the culture result before choosing any antibiotic','Delay can be fatal.'),('Use oral outpatient treatment because fever is the only infection sign','Hypotension and profound neutropenia indicate high risk.'),('Give G-CSF alone as the immediate infection treatment','Growth-factor support does not replace antimicrobials and resuscitation.')],
 'Sparse inflammatory signs do not imply low risk','**Neutropenia can permit rapid bacterial deterioration.**',['Obtain cultures promptly when this does not delay treatment.','Assess organ dysfunction, lactate and likely sources.'],'**Use local resistance, allergy and prior colonization information.**',['Support circulation and oxygenation as indicated.','Escalate early to experienced oncology/infection/critical-care teams.'],[['Risk','Profound neutropenia plus instability'],['Immediate treatment','IV antibiotics/resuscitation'],['Cultures','Prompt, without harmful delay']],[FN,NS],style='clinical_scenario')

q('Which blood-culture strategy is appropriate at initial febrile-neutropenia assessment when a central line is present and sampling will not delay antibiotics?', 'Obtain suitable peripheral and central-line cultures, including relevant lumens according to protocol',[
 ('Culture only after several days of antibiotics','This reduces diagnostic yield.'),('Culture only the urine regardless of presentation','Bloodstream infection is an important concern.'),('Do not culture because neutropenia prevents bacteremia','It increases rather than removes the risk.')],
 'Sampling can identify organism and possible line involvement','**Paired appropriately labeled cultures can help source assessment.**',['Use aseptic technique and correct volume.','Do not delay urgent antimicrobials for difficult access.'],'**Reassess source control after results and clinical review.**',['A line is not automatically the source of every fever.','Other site investigations follow symptoms and risk.'],[['Peripheral','Bloodstream assessment'],['Line samples','Potential catheter source'],['Priority','No treatment delay']],[FN])

q('For initial inpatient therapy of uncomplicated high-risk febrile neutropenia, which drug among these provides appropriate antipseudomonal beta-lactam coverage?', 'Cefepime',[
 ('Ceftriaxone alone','It does not provide reliable Pseudomonas coverage.'),('Amoxicillin alone','It is inadequate for this high-risk empirical setting.'),('Vancomycin alone','It does not cover the essential Gram-negative spectrum.')],
 'Early coverage must include dangerous Gram-negative pathogens','**An appropriate antipseudomonal beta-lactam is a usual backbone.**',['Other accepted choices include piperacillin–tazobactam or a suitable carbapenem according to context.','Resistance, allergy and organ function can change the regimen.'],'**Use the local guideline and revise with clinical/microbiological evidence.**',['Add specific coverage when indicated.','Avoid assuming one agent is optimal in every resistance setting.'],[['Backbone','Antipseudomonal beta-lactam'],['Gram-positive agents alone','Insufficient'],['Selection','Local risk and susceptibility']],[FN,NS])

q('A stable febrile-neutropenic patient has no catheter infection signs, pneumonia, skin infection or known resistant Gram-positive risk. Which vancomycin principle is correct?', 'It is not routinely required solely because a central venous catheter exists',[
 ('Every central line mandates empirical vancomycin','Specific clinical or microbiological indications are needed.'),('Vancomycin replaces the antipseudomonal backbone','It does not provide the needed Gram-negative coverage.'),('It is forbidden if hemodynamic instability or a compatible resistant infection later develops','New indications can justify it.')],
 'Broaden coverage for a reason','**Routine glycopeptide use is not the default for every febrile-neutropenic patient.**',['Instability and selected suspected sources can change the decision.','Resistance history and local epidemiology matter.'],'**Review empirical additions as evidence emerges.**',['Avoid unnecessary nephrotoxicity and resistance pressure.','Do not undertreat a genuine high-risk Gram-positive presentation.'],[['Line present','Not sufficient alone'],['Indications','Clinical/microbiological risk'],['Review','De-escalate when appropriate']],[FN,NS],style='clinical_scenario')

q('A patient appears low risk on a febrile-neutropenia score but has poor oral intake, unreliable transport and no rapid access to review. Which disposition principle is appropriate?', 'Do not use the score alone to justify outpatient care; clinical and logistical suitability are essential',[
 ('A numerical low-risk category guarantees safe discharge','Scores do not capture every clinical and social constraint.'),('Oral therapy is adequate even if medication cannot be retained','Absorption and adherence feasibility matter.'),('The absence of a documented organism proves low risk','Initial cultures are often uninformative.')],
 'Outpatient eligibility is more than a score','**Stability, anticipated neutropenia, comorbidity and reliable follow-up must be assessed.**',['A suitable oral regimen also depends on prior prophylaxis and resistance risk.','Clear escalation instructions and access are essential.'],'**Choose a monitored setting when those conditions are not met.**',['Reassess as the course evolves.','Avoid using a tool to overrule obvious unsuitability.'],[['Score','One input'],['Clinical','Stability/intake/comorbidity'],['Logistics','Access and reliable follow-up']],[FN,ref('ASCO/IDSA outpatient fever/neutropenia guidance','https://www.idsociety.org/practice-guideline/outpatient-management-of-fever-and-neutropenia-in-adults-treated-for-malignancy/')],style='clinical_scenario')

q('A profoundly neutropenic patient receiving steroids has new confusion and shock but no fever. Which interpretation is appropriate?', 'Serious infection and neutropenic sepsis remain possible and need immediate evaluation and treatment',[
 ('No fever excludes sepsis','Immunosuppression can blunt fever and inflammation.'),('Confusion must be a primary psychiatric reaction to cancer','Medical causes must be assessed urgently.'),('Antibiotics should wait until temperature reaches a fixed threshold','Instability and infection suspicion can require treatment without fever.')],
 'Immunosuppression changes the presentation','**Neutropenic patients can have muted inflammatory signs.**',['Review infection, medication, metabolic and other shock causes.','Treat the immediately dangerous physiology.'],'**Use a prompt sepsis pathway with appropriate empirical coverage.**',['Obtain cultures without delaying treatment.','Assess source and organ-support needs.'],[['Fever','May be absent'],['Red flags','Shock/confusion'],['Action','Urgent medical treatment']],[FN,NS],style='clinical_scenario')

q('Persistent fever continues after several days of broad-spectrum antibiotics in a patient expected to have prolonged profound neutropenia. Which next issue is important?', 'Reassess for invasive fungal infection and use an appropriate empirical or diagnostic-driven antifungal strategy',[
 ('Repeat the same antibacterial plan indefinitely without investigation','Persistent high-risk fever requires reassessment.'),('Give antifungals to every brief low-risk fever identically','Risk and expected neutropenia duration determine the strategy.'),('Assume fever proves antibacterial resistance alone','Fungi and noninfectious causes are possible.')],
 'The differential evolves with time and immune deficit','**Prolonged profound neutropenia increases invasive fungal risk.**',['Imaging, biomarkers, prior prophylaxis and stability guide the approach.','Noninfectious fever and occult bacterial sources remain possible.'],'**Involve infection expertise and tailor treatment.**',['Do not use a fixed day count without clinical context.','Review drug interactions and organ toxicity.'],[['Risk','Prolonged profound neutropenia'],['Assessment','Fungal and other causes'],['Strategy','Empirical or diagnostic-driven as appropriate']],[FN],style='clinical_scenario')

q('A neutropenic chemotherapy patient has fever, right lower-quadrant pain and bowel-wall thickening centered on the cecum. Which syndrome is most likely?', 'Neutropenic enterocolitis',[
 ('Uncomplicated IBS','Fever, neutropenia and imaging changes indicate a dangerous inflammatory syndrome.'),('Isolated acute appendicitis as the only possible diagnosis','Appendicitis is a differential, but the cecal pattern in profound neutropenia suggests typhlitis.'),('A benign drug-related cramp that requires no reassessment','Complications can include sepsis, bleeding and perforation.')],
 'Mucosal injury and neutropenia can create a bowel emergency','**Typhlitis requires prompt supportive and antimicrobial management.**',['Use imaging and assess for perforation or uncontrolled bleeding.','Broad coverage must account for enteric organisms and anaerobes.'],'**Coordinate oncology, infection and surgical assessment as indicated.**',['Avoid routine traumatic rectal procedures or colonoscopy in the acute high-risk setting.','Surgery is selected for complications rather than automatic in every case.'],[['Context','Neutropenia/chemotherapy'],['Site','Often ileocecal'],['Care','Support, antibiotics and complication assessment']],[FN],style='clinical_scenario')
